    if directory is not None:
        return Mount("/", app=StaticFiles(directory=directory, html=True))

    async def missing(request: Any) -> PlainTextResponse:
        return PlainTextResponse("no web/dist; run `npm -C web run build`\n", status_code=404)

    return Route("/{path:path}", missing)


