SECRETS = ["CODEX_OAUTH_TOKEN","GOOGLE_API_KEY","OPENAI_API_KEY","ANTHROPIC_API_KEY","NPM_TOKEN","CLAWHUB_TOKEN","CHROME_EXTENSION_ID","CHROME_PUBLISHER_ID","CHROME_SERVICE_ACCOUNT_CLIENT_EMAIL","CHROME_SERVICE_ACCOUNT_PRIVATE_KEY","FIREFOX_EXTENSION_ID","FIREFOX_JWT_ISSUER","FIREFOX_JWT_SECRET","EDGE_PRODUCT_ID","EDGE_CLIENT_ID","EDGE_API_KEY"]


def env_path() -> Path:
    return Path.cwd() / ".env"


